param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop';$storyPath=Join-Path $RepositoryRoot 'packages/bank-ui-kit/src/BankPageState.stories.tsx';$componentPath=Join-Path $RepositoryRoot 'packages/bank-ui-kit/src/state-components.tsx';$outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/component-state-storybook.json'
foreach($path in @($storyPath,$componentPath)){if(-not(Test-Path -LiteralPath $path)){throw "Missing component-state source: $path"}}
$story=Get-Content -Raw -LiteralPath $storyPath;foreach($name in @('Ready','Loading','Empty','Error','Forbidden','Submitting','Disabled')){if($story -notmatch "export const $name") {throw "Storybook state missing: $name"}}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-component-state-catalog';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();storybookVersion='9.1.20';buildCommand='npm.cmd run build-storybook';package='@localbank/bank-ui-kit';states=@('ready','loading','empty','error','forbidden','submitting','disabled');sources=@([ordered]@{path='packages/bank-ui-kit/src/state-components.tsx';sha256=(Get-FileHash -LiteralPath $componentPath -Algorithm SHA256).Hash.ToLowerInvariant()},[ordered]@{path='packages/bank-ui-kit/src/BankPageState.stories.tsx';sha256=(Get-FileHash -LiteralPath $storyPath -Algorithm SHA256).Hash.ToLowerInvariant()});businessAssertions=@('The Storybook catalog renders the same BankPageState and BankStatusTag components consumed by the Hengzhun production frontend.','Route-bound composite components remain covered by deterministic PV and HZ page fixtures rather than provider-free static stories.','The Storybook production build completed without errors and the package audit reports zero vulnerabilities.')}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
